import React, { useEffect, useMemo, useState } from 'react';
import { IncidentPublicReportFilters } from '../../../models/IncidentPublicReport';
import { useFormOptions } from '../../../hooks/useFormOptions';
import styles from './PublicReportFiltersBar.module.css';
import {
  LinErpListFilterBar,
  SearchTextInput,
  Select,
} from '@linm-soft-org/linm-web-common-components';

const TEST_ID_PREFIX = 'incident-public-report';

interface Props {
  filters: IncidentPublicReportFilters;
  onChange: (f: IncidentPublicReportFilters) => void;
  onClear: () => void;
  loading?: boolean;
}

export const PublicReportFiltersBar: React.FC<Props> = ({
  filters,
  onChange,
  onClear,
  loading = false,
}) => {
  const [draft, setDraft] = useState<IncidentPublicReportFilters>(filters);
  const {
    departmentOptions,
    publicReportStatusOptions,
    publicReportLabel: L,
  } = useFormOptions('public-report-list');

  useEffect(() => {
    setDraft(filters);
  }, [filters]);

  const statusOptions = useMemo(
    () => [{ value: '', label: L('allStatus') }, ...publicReportStatusOptions],
    [publicReportStatusOptions, L],
  );

  const deptOptions = useMemo(
    () => [{ value: '', label: L('allDept') }, ...departmentOptions],
    [departmentOptions, L],
  );

  const hasActiveFilters = !!(draft.search || draft.status || draft.departmentId);

  const handleSearch = () => {
    onChange({
      search: draft.search?.trim() || undefined,
      status: draft.status || undefined,
      departmentId: draft.departmentId || undefined,
    });
  };

  const handleClear = () => {
    setDraft({});
    onClear();
  };

  return (
    <LinErpListFilterBar
      testIdPrefix={TEST_ID_PREFIX}
      onSearch={handleSearch}
      loading={loading}
      leading={(
        <>
          <div data-testid={`${TEST_ID_PREFIX}-field-search`}>
            <SearchTextInput
              label={L('search')}
              placeholder={L('searchPlaceholder')}
              value={draft.search ?? ''}
              onChange={(search) => setDraft((prev) => ({ ...prev, search }))}
              testId={`${TEST_ID_PREFIX}-search-text`}
            />
          </div>
          <div data-testid={`${TEST_ID_PREFIX}-field-status`}>
            <Select
              label={L('status')}
              options={statusOptions}
              value={draft.status ?? ''}
              onChange={(e) => setDraft((prev) => ({ ...prev, status: e.target.value }))}
              size="small"
            />
          </div>
          <div data-testid={`${TEST_ID_PREFIX}-field-department`}>
            <Select
              label={L('department')}
              options={deptOptions}
              value={draft.departmentId ?? ''}
              onChange={(e) => setDraft((prev) => ({ ...prev, departmentId: e.target.value }))}
              size="small"
            />
          </div>
          {hasActiveFilters && (
            <div data-testid={`${TEST_ID_PREFIX}-field-clear`}>
              <button
                className={styles.clearFiltersButton}
                onClick={handleClear}
                type="button"
                title={L('clearFilters')}
              >
                <i className="fas fa-times-circle" />
                <span>{L('clearFilters')}</span>
              </button>
            </div>
          )}
        </>
      )}
    />
  );
};
