import React from 'react';
import { Button } from '@linm-soft-org/linm-web-common-components';
import type { IncidentPublicReportPoster } from '../../../models/IncidentPublicReport';
import styles from './PublicReportQrModal.module.css';

interface Props {
  poster: IncidentPublicReportPoster;
  qrUrl: string;
  publicUrl: string;
  label: (key: string) => string;
  onClose: () => void;
  onPrint: () => void;
}

export const PublicReportQrModal: React.FC<Props> = ({
  poster, qrUrl, publicUrl, label, onClose, onPrint,
}) => (
  <div className={styles.overlay} data-testid="incident-public-report-qr-modal">
    <div className={styles.dialog} role="dialog">
      <h3>{label('qr')}</h3>
      <p className={styles.company}>{poster.companyName}</p>
      <img className={styles.qr} src={qrUrl} alt="" />
      <p className={styles.hint}>{label('posterHint')}</p>
      <p className={styles.url}>{publicUrl}</p>
      <div className={styles.actions}>
        <Button variant="secondary" onClick={onClose}>{label('close')}</Button>
        <Button variant="primary" onClick={onPrint}>
          <i className="fas fa-print" /> {label('print')}
        </Button>
      </div>
    </div>
  </div>
);
